using System.Text.RegularExpressions;
using FluentValidation;
using Zladovce.Application.Cart;
using Zladovce.Application.Common.Errors;
using Zladovce.Domain.Catalog;
using Zladovce.Domain.Common;
using Zladovce.Domain.Orders;

namespace Zladovce.Application.Orders;

/// <summary>
/// Body of <c>POST /api/v1/orders</c>. The client sends variant ids and quantities only; every price comes from the database.
/// The <c>Idempotency-Key</c> header (a UUID generated by the browser when checkout opens) is required.
/// </summary>
public sealed record CreateOrderRequest
{
    /// <summary>1–50 lines; lines with the same variant are merged (as in the cart quote).</summary>
    public required IReadOnlyList<CreateOrderItemRequest>? Items { get; init; }

    public required CheckoutCustomerRequest? Customer { get; init; }

    public required CheckoutAddressRequest? Address { get; init; }

    /// <summary>Optional note for the courier, up to 500 characters.</summary>
    public string? DeliveryNote { get; init; }

    /// <summary>Must be <c>true</c>: the customer accepted the terms of purchase.</summary>
    public required bool? AcceptedTerms { get; init; }

    /// <summary>
    /// Optional: the <c>total</c> of the quote the customer confirmed. When it differs from the total computed now
    /// (for example because the shipping price changed), the order is refused with 409 <c>CART_CHANGED</c>.
    /// </summary>
    public decimal? ExpectedTotal { get; init; }
}

/// <summary>One line of the order.</summary>
public sealed record CreateOrderItemRequest
{
    public required Guid? VariantId { get; init; }

    /// <summary>1–99.</summary>
    public required int? Quantity { get; init; }

    /// <summary>
    /// Optional: the <c>unitPrice</c> of the quote the customer confirmed. A different current price refuses the order with
    /// 409 <c>CART_CHANGED</c>. Never used for pricing.
    /// </summary>
    public decimal? KnownUnitPrice { get; init; }
}

public sealed record CheckoutCustomerRequest
{
    /// <summary>Up to 100 characters: letters, spaces, hyphen, apostrophe, dot.</summary>
    public required string? FirstName { get; init; }

    /// <summary>Up to 100 characters: letters, spaces, hyphen, apostrophe, dot.</summary>
    public required string? LastName { get; init; }

    /// <summary>Up to 254 characters.</summary>
    public required string? Email { get; init; }

    /// <summary>Serbian number: <c>+381 64 123 4567</c>, <c>00381…</c> or <c>064 123 4567</c>. Stored in E.164 (<c>+381641234567</c>).</summary>
    public required string? Phone { get; init; }
}

public sealed record CheckoutAddressRequest
{
    /// <summary>Up to 100 characters.</summary>
    public required string? City { get; init; }

    /// <summary>Street and house number, up to 200 characters.</summary>
    public required string? Street { get; init; }

    /// <summary>Exactly five digits.</summary>
    public required string? PostalCode { get; init; }
}

public static partial class CheckoutRules
{
    public const int MaxNameLength = 100;
    public const int MaxEmailLength = 254;
    public const int MaxPhoneLength = 30;
    public const int MaxCityLength = 100;
    public const int MaxStreetLength = 200;

    [GeneratedRegex(@"^\p{L}[\p{L}\p{M} .'’\-]*$")]
    public static partial Regex NamePattern();

    [GeneratedRegex(@"^[^@\s]+@[^@\s]+\.[^@\s.]{2,}$")]
    public static partial Regex EmailPattern();
}

public sealed class CreateOrderRequestValidator : AbstractValidator<CreateOrderRequest>
{
    public CreateOrderRequestValidator()
    {
        RuleFor(r => r.Items)
            .NotEmpty().WithMessage("Korpa je prazna.")
            .Must(items => items is null || items.Count <= CartQuoteRequest.MaxItems)
            .WithMessage($"Porudžbina može imati najviše {CartQuoteRequest.MaxItems} stavki.");
        RuleForEach(r => r.Items).NotNull().SetValidator(new CreateOrderItemRequestValidator());

        RuleFor(r => r.Customer).NotNull().WithMessage("Podaci o kupcu su obavezni.").SetValidator(new CheckoutCustomerRequestValidator()!);
        RuleFor(r => r.Address).NotNull().WithMessage("Adresa za dostavu je obavezna.").SetValidator(new CheckoutAddressRequestValidator()!);

        RuleFor(r => r.DeliveryNote)
            .MaximumLength(Order.MaxDeliveryNoteLength)
            .WithMessage($"Napomena može imati najviše {Order.MaxDeliveryNoteLength} znakova.");

        RuleFor(r => r.AcceptedTerms)
            .NotNull().WithMessage("Morate prihvatiti uslove kupovine.")
            .Equal(true).WithMessage("Morate prihvatiti uslove kupovine.");

        RuleFor(r => r.ExpectedTotal)
            .GreaterThanOrEqualTo(0)
            .LessThanOrEqualTo(Pricing.MaxPrice)
            .Must(total => total is null || Pricing.HasAtMostTwoDecimals(total.Value))
            .WithMessage("Iznos može imati najviše dve decimale.");
    }
}

public sealed class CreateOrderItemRequestValidator : AbstractValidator<CreateOrderItemRequest>
{
    public CreateOrderItemRequestValidator()
    {
        RuleFor(i => i.VariantId)
            .NotNull()
            .Must(id => id != Guid.Empty)
            .WithMessage("Identifikator varijante je obavezan.");
        RuleFor(i => i.Quantity)
            .NotNull()
            .InclusiveBetween(1, CartQuoteRequest.MaxQuantity)
            .WithMessage($"Količina mora biti između 1 i {CartQuoteRequest.MaxQuantity}.");
        RuleFor(i => i.KnownUnitPrice)
            .GreaterThan(0)
            .LessThanOrEqualTo(Pricing.MaxPrice)
            .Must(price => price is null || Pricing.HasAtMostTwoDecimals(price.Value))
            .WithMessage("Cena može imati najviše dve decimale.");
    }
}

public sealed class CheckoutCustomerRequestValidator : AbstractValidator<CheckoutCustomerRequest>
{
    public CheckoutCustomerRequestValidator()
    {
        Name(RuleFor(c => c.FirstName), "Ime");
        Name(RuleFor(c => c.LastName), "Prezime");

        RuleFor(c => c.Email)
            .Cascade(CascadeMode.Stop)
            .Must(v => !string.IsNullOrWhiteSpace(v)).WithMessage("Adresa e-pošte je obavezna.")
            .Must(v => v!.Trim().Length <= CheckoutRules.MaxEmailLength).WithMessage($"Adresa e-pošte može imati najviše {CheckoutRules.MaxEmailLength} znakova.")
            .Must(v => CheckoutRules.EmailPattern().IsMatch(v!.Trim())).WithMessage("Unesite ispravnu adresu e-pošte (npr. ime@primer.rs).");

        RuleFor(c => c.Phone)
            .Cascade(CascadeMode.Stop)
            .Must(v => !string.IsNullOrWhiteSpace(v)).WithMessage("Broj telefona je obavezan.")
            .Must(v => v!.Length <= CheckoutRules.MaxPhoneLength && SerbianPhone.Normalize(v) is not null)
            .WithMessage("Unesite ispravan broj telefona u Srbiji, npr. 064 123 4567 ili +381 64 123 4567.");
    }

    private static void Name(IRuleBuilderInitial<CheckoutCustomerRequest, string?> rule, string label) =>
        rule.Cascade(CascadeMode.Stop)
            .Must(v => !string.IsNullOrWhiteSpace(v)).WithMessage($"{label} je obavezno.")
            .Must(v => v!.Trim().Length <= CheckoutRules.MaxNameLength).WithMessage($"{label} može imati najviše {CheckoutRules.MaxNameLength} znakova.")
            .Must(v => CheckoutRules.NamePattern().IsMatch(v!.Trim()))
            .WithMessage($"{label} sme da sadrži samo slova, razmak, crticu, tačku i apostrof.");
}

public sealed class CheckoutAddressRequestValidator : AbstractValidator<CheckoutAddressRequest>
{
    public CheckoutAddressRequestValidator()
    {
        RuleFor(a => a.City)
            .Cascade(CascadeMode.Stop)
            .Must(v => !string.IsNullOrWhiteSpace(v)).WithMessage("Mesto je obavezno.")
            .Must(v => v!.Trim().Length <= CheckoutRules.MaxCityLength).WithMessage($"Mesto može imati najviše {CheckoutRules.MaxCityLength} znakova.");

        RuleFor(a => a.Street)
            .Cascade(CascadeMode.Stop)
            .Must(v => !string.IsNullOrWhiteSpace(v)).WithMessage("Ulica i broj su obavezni.")
            .Must(v => v!.Trim().Length <= CheckoutRules.MaxStreetLength).WithMessage($"Ulica i broj mogu imati najviše {CheckoutRules.MaxStreetLength} znakova.");

        RuleFor(a => a.PostalCode)
            .Cascade(CascadeMode.Stop)
            .Must(v => !string.IsNullOrWhiteSpace(v)).WithMessage("Poštanski broj je obavezan.")
            .Must(v => SerbianPostalCode.IsValid(v!.Trim())).WithMessage("Poštanski broj ima tačno 5 cifara.");
    }
}

/// <summary>One item of a placed order (snapshot).</summary>
public sealed record PlacedOrderItem(Guid VariantId, string ProductName, string VariantName, string Sku, decimal UnitPrice, int Quantity, decimal LineTotal);

/// <summary>
/// Response of <c>POST /api/v1/orders</c> (201 new order, 200 replay of the same request).
/// </summary>
/// <param name="Items">Item snapshots, sorted by product name, variant name and SKU.</param>
/// <param name="TrackingCode">
/// The internal tracking code, shown once. Always null until tracking codes exist (Phase 6); on a replay it stays null even then,
/// because the plain code is never stored.
/// </param>
public sealed record PlacedOrderResponse(
    string OrderNumber,
    DateTimeOffset PlacedAt,
    IReadOnlyList<PlacedOrderItem> Items,
    decimal Subtotal,
    decimal ShippingPrice,
    decimal Total,
    string Currency,
    PaymentMethod PaymentMethod,
    string? TrackingCode)
{
    public static PlacedOrderResponse From(Order order) => new(
        order.OrderNumber,
        order.PlacedAt,
        [.. order.Items
            .OrderBy(i => i.ProductName, StringComparer.Ordinal).ThenBy(i => i.VariantName, StringComparer.Ordinal).ThenBy(i => i.Sku, StringComparer.Ordinal)
            .Select(i => new PlacedOrderItem(i.VariantId, i.ProductName, i.VariantName, i.Sku, i.UnitPrice, i.Quantity, i.LineTotal))],
        order.Subtotal,
        order.ShippingPrice,
        order.Total,
        Money.Currency,
        order.PaymentMethod,
        TrackingCode: null);
}

/// <param name="Created">True for a new order (201), false for a replay of an earlier identical request (200).</param>
public sealed record CheckoutResult(PlacedOrderResponse Order, bool Created);

/// <summary>
/// 409 from checkout that carries the cart priced again (<see cref="Quote"/>), so the shop can show the customer what
/// changed: <c>CART_CHANGED</c>, <c>INSUFFICIENT_STOCK</c>, <c>MINIMUM_ORDER_NOT_MET</c>, <c>SHIPPING_DISABLED</c>.
/// Nothing was stored.
/// </summary>
public sealed class CheckoutConflictException(
    string code,
    string title,
    string detail,
    CartQuoteResponse quote,
    IReadOnlyDictionary<string, string[]>? errors = null) : AppException(code, title, detail)
{
    public CartQuoteResponse Quote { get; } = quote;

    /// <summary>Field path of the request (<c>items[i].quantity</c>, <c>expectedTotal</c>) → messages.</summary>
    public IReadOnlyDictionary<string, string[]>? Errors { get; } = errors;
}
